;window.C3K_WORLD_PORTS_REFERENCE=window.C3K_WORLD_PORTS_REFERENCE||{};
(() => {
  'use strict';
  const REG=window.C3K_WORLD_PORTS_REFERENCE||{meta:{counts:{}},ports:[],terminals:[],operators:[],countries:[]};
  const byId=id=>document.getElementById(id);
  const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
  const flag=iso=>{const c=String(iso||'').toUpperCase();return /^[A-Z]{2}$/.test(c)?String.fromCodePoint(...[...c].map(x=>127397+x.charCodeAt(0))):'🌐';};
  const split=v=>String(v||'').split(/\s*;\s*/).map(x=>x.trim()).filter(Boolean);
  const safeUrl=v=>{try{const u=new URL(String(v||''));return /^https?:$/.test(u.protocol)?u.href:'';}catch{return '';}};
  const statusKind=v=>{const n=norm(v);return n.includes('histor')||n.includes('ferme')?'history':n.includes('verifier')||n.includes('controle')||n.includes('mixte')?'check':'active';};
  const aliasByKey=new Map((REG.terminals||[]).map(t=>[t.key,(t.aliases||[])]));
  let tab='ports',query='',country='all',status='all';
  const RENDER_LIMIT=160;
  function portScore(row,q){
    const nq=norm(q); if(!nq)return 10;
    const compact=nq.replace(/\s+/g,'');
    const un=norm(row.unlocode);
    if(un===compact||un===nq)return -100;
    if(norm(row.location)===nq)return -75;
    const codes=split(row.terminalCodes).map(norm);
    if(codes.includes(nq))return -70;
    const hay=norm([row.unlocode,row.iso2,row.country,row.location,row.altUnlocodes,row.terminalCodes,row.terminals,row.operators,row.addresses,row.search].join(' '));
    if(hay.includes(nq))return -30;
    const toks=nq.split(' ').filter(Boolean); if(toks.length>1&&toks.every(t=>hay.includes(t)))return -20;
    return Infinity;
  }
  function terminalScore(row,q){
    const nq=norm(q); if(!nq)return 10;
    const key=norm(row.key),code=norm(row.code),un=norm(row.unlocode);
    if(key===nq||code===nq)return -100;
    if(un===nq)return -90;
    const aliases=aliasByKey.get(row.key)||[];
    if(aliases.some(a=>norm(a.alias)===nq))return -80;
    const hay=norm([row.key,row.unlocode,row.altUnlocode,row.code,row.name,row.operator,row.country,row.address,row.remarks,row.search,...aliases.map(a=>a.alias)].join(' '));
    if(hay.includes(nq))return -30;
    const toks=nq.split(' ').filter(Boolean); if(toks.length>1&&toks.every(t=>hay.includes(t)))return -20;
    return Infinity;
  }
  function operatorScore(row,q){
    const nq=norm(q); if(!nq)return 10;
    const name=norm(row.name); if(name===nq)return -100;if(name.startsWith(nq))return -70;
    const hay=norm([row.name,row.normalized,row.iso2,row.unlocodes,row.search].join(' '));
    if(hay.includes(nq))return -30;
    const toks=nq.split(' ').filter(Boolean); if(toks.length>1&&toks.every(t=>hay.includes(t)))return -20;
    return Infinity;
  }
  function countryOk(row){if(country==='all')return true;return String(row.iso2||'').split(/\s*;\s*/).includes(country);}
  function statusOk(row){return status==='all'||statusKind(row.status)===status;}
  function resultRows(){
    const src=tab==='terminals'?REG.terminals:tab==='operators'?REG.operators:REG.ports;
    const scoreFn=tab==='terminals'?terminalScore:tab==='operators'?operatorScore:portScore;
    return (src||[]).map(row=>({row,score:scoreFn(row,query)}))
      .filter(x=>Number.isFinite(x.score)&&countryOk(x.row)&&(tab==='operators'||statusOk(x.row)))
      .sort((a,b)=>a.score-b.score||(tab==='operators'?String(a.row.name).localeCompare(String(b.row.name),'fr'):String(a.row.unlocode||a.row.code).localeCompare(String(b.row.unlocode||b.row.code),'fr')))
      .map(x=>x.row);
  }
  function websiteButton(url,label='Site'){const u=safeUrl(url);return u?`<a class="world-ports-link" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';}
  function statusBadge(row){const k=statusKind(row.status);return `<span class="world-ports-status is-${k}">${esc(row.status||'—')}</span>`;}
  function portCard(row){
    const terminalNames=split(row.terminals); const ops=split(row.operators); const sites=split(row.websites);
    return `<article class="world-ports-card" data-world-port="${esc(row.unlocode)}" data-c3k-ref="ports_world" data-c3k-collection="ports" data-c3k-key="${esc(row.unlocode)}">
      <div class="world-ports-card-head"><div><span class="world-ports-code">${esc(row.unlocode)}</span><span class="world-ports-flag">${flag(row.iso2)}</span><strong>${esc(row.country)}</strong></div>${statusBadge(row)}</div>
      <div class="world-ports-card-title">${row.terminalCount} ${row.terminalCount>1?'terminaux':'terminal'} SMDG <span>· ${esc(row.location)}</span></div>
      <div class="world-ports-card-copy">${terminalNames.slice(0,4).map(esc).join(' · ')}${terminalNames.length>4?` <em>+${terminalNames.length-4}</em>`:''}</div>
      <div class="world-ports-card-meta"><span><b>Codes :</b> ${esc(row.terminalCodes||'—')}</span><span><b>Opérateurs :</b> ${ops.slice(0,3).map(esc).join(' · ')}${ops.length>3?' …':''}</span></div>
      ${row.addresses?`<div class="world-ports-address">${esc(split(row.addresses)[0])}</div>`:''}
      <div class="world-ports-card-foot"><button type="button" class="world-ports-secondary" data-world-terminals="${esc(row.unlocode)}">Voir les terminaux</button>${sites.length?websiteButton(sites[0],'Site') : ''}<span class="world-ports-source">${esc(row.source||REG.meta?.version||'')}</span></div>
    </article>`;
  }
  function terminalCard(row){
    const aliases=(aliasByKey.get(row.key)||[]).filter(a=>norm(a.alias)!==norm(row.code)).slice(0,6);
    return `<article class="world-ports-card world-ports-terminal" data-world-terminal="${esc(row.key)}" data-c3k-ref="ports_world" data-c3k-collection="terminals" data-c3k-key="${esc(row.key)}">
      <div class="world-ports-card-head"><div><span class="world-ports-code">${esc(row.unlocode)}</span><span class="world-ports-terminal-code">${esc(row.code||'—')}</span><span class="world-ports-flag">${flag(row.iso2)}</span></div>${statusBadge(row)}</div>
      <h3>${esc(row.name||row.key)}</h3>
      <div class="world-ports-operator">${esc(row.operator||'Opérateur non renseigné')}</div>
      <div class="world-ports-card-meta"><span>${esc(row.country)}</span>${row.address?`<span>${esc(row.address)}</span>`:''}${row.remarks?`<span>${esc(row.remarks)}</span>`:''}</div>
      ${aliases.length?`<div class="world-ports-aliases"><b>Alias :</b> ${aliases.map(a=>`<span>${esc(a.alias)}</span>`).join('')}</div>`:''}
      <div class="world-ports-card-foot">${websiteButton(row.website,'Site terminal')}<button type="button" class="world-ports-secondary" data-world-port-parent="${esc(row.unlocode)}">Voir le port</button><span class="world-ports-source">${esc(row.source||'')}</span></div>
    </article>`;
  }
  function operatorCard(row){
    const un=split(row.unlocodes);
    return `<article class="world-ports-card world-ports-operator-card" data-c3k-ref="ports_world" data-c3k-collection="operators" data-c3k-key="${esc(row.name)}">
      <div class="world-ports-card-head"><div><span class="world-ports-flag">${flag((row.iso2||'').split(/\s+/)[0])}</span><strong>${esc(row.name)}</strong></div><span class="world-ports-count-badge">${row.terminalCount} ${row.terminalCount>1?'terminaux':'terminal'}</span></div>
      <div class="world-ports-card-title">${row.portCount} port${row.portCount>1?'s':''} · ${row.countryCount} pays/territoire${row.countryCount>1?'s':''}</div>
      <div class="world-ports-card-copy">${un.slice(0,12).map(x=>`<button type="button" class="world-ports-code-chip" data-world-port-parent="${esc(x)}">${esc(x)}</button>`).join('')}${un.length>12?` <em>+${un.length-12}</em>`:''}</div>
      <div class="world-ports-card-foot"><span class="world-ports-source">${esc(row.source||'')}</span></div>
    </article>`;
  }
  function render(){
    const grid=byId('worldPortsGrid'),count=byId('worldPortsCount'),empty=byId('worldPortsEmpty'); if(!grid)return;
    const rows=resultRows(); const visible=rows.slice(0,RENDER_LIMIT);
    grid.innerHTML=visible.map(row=>tab==='terminals'?terminalCard(row):tab==='operators'?operatorCard(row):portCard(row)).join('');window.C3K_REFERENCE_EDITOR?.bind(grid);
    if(count)count.textContent=`${rows.length.toLocaleString('fr-FR')} résultat${rows.length>1?'s':''}${rows.length>RENDER_LIMIT?` · ${RENDER_LIMIT} affichés`:''}`;
    if(empty)empty.hidden=rows.length>0;
    document.querySelectorAll('[data-world-tab]').forEach(b=>b.classList.toggle('is-active',b.dataset.worldTab===tab));
    const statusWrap=byId('worldPortsStatusWrap'); if(statusWrap)statusWrap.hidden=tab==='operators';
  }
  function setTab(next){tab=['ports','terminals','operators'].includes(next)?next:'ports';render();}
  function open(opts={}){
    const modal=byId('worldPortsModal'); if(!modal)return;
    modal.hidden=false;document.body.classList.add('modal-open');
    if(opts.tab)tab=opts.tab;
    if(opts.query!==undefined)query=String(opts.query||'');
    if(opts.country!==undefined)country=String(opts.country||'all');
    if(opts.status!==undefined)status=String(opts.status||'all');
    const input=byId('worldPortsSearch'),countrySel=byId('worldPortsCountry'),statusSel=byId('worldPortsStatus');
    if(input)input.value=query;if(countrySel)countrySel.value=country;if(statusSel)statusSel.value=status;
    render();requestAnimationFrame(()=>input?.focus());
  }
  function close(){const modal=byId('worldPortsModal');if(modal)modal.hidden=true;if(!document.querySelector('.modal-overlay:not([hidden]),.adr-reference-modal:not([hidden]),.world-ports-modal:not([hidden])'))document.body.classList.remove('modal-open');}
  function build(){
    if(byId('worldPortsModal'))return;
    const counts=REG.meta?.counts||{};
    const countryOptions=(REG.countries||[]).slice().sort((a,b)=>String(a.country).localeCompare(String(b.country),'fr')).map(c=>`<option value="${esc(c.iso2)}">${flag(c.iso2)} ${esc(c.country)} · ${c.portCount} ports</option>`).join('');
    document.body.insertAdjacentHTML('beforeend',`<div class="world-ports-modal" id="worldPortsModal" hidden>
      <section class="world-ports-dialog" role="dialog" aria-modal="true" aria-labelledby="worldPortsTitle">
        <header class="world-ports-head"><div><h2 id="worldPortsTitle">Ports mondiaux conteneurisés — SMDG</h2><div>${(counts.ports||0).toLocaleString('fr-FR')} ports · ${(counts.terminals||0).toLocaleString('fr-FR')} terminaux · ${(counts.countries||0).toLocaleString('fr-FR')} pays/territoires · ${(counts.operators||0).toLocaleString('fr-FR')} opérateurs</div></div><button type="button" id="worldPortsClose" aria-label="Fermer">×</button></header>
        <div class="world-ports-body">
          <div class="world-ports-notice"><strong>Référentiel SMDG.</strong> La vue Ports agrège uniquement par UNLOCODE ; les ${(counts.terminals||0).toLocaleString('fr-FR')} lignes terminal restent conservées individuellement. Les lignes à vérifier et historiques ne sont pas supprimées.</div>
          <div class="world-ports-tabs"><button type="button" data-world-tab="ports" class="is-active">Ports <span>${counts.ports||0}</span></button><button type="button" data-world-tab="terminals">Terminaux <span>${counts.terminals||0}</span></button><button type="button" data-world-tab="operators">Opérateurs <span>${counts.operators||0}</span></button></div>
          <div class="world-ports-controls"><input id="worldPortsSearch" type="search" autocomplete="off" spellcheck="false" placeholder="BEANR, Rotterdam, FRLEH, QATL, PSA, DP World…"/><select id="worldPortsCountry"><option value="all">Tous les pays / territoires</option>${countryOptions}</select><label id="worldPortsStatusWrap"><select id="worldPortsStatus"><option value="all">Tous les statuts</option><option value="active">Actifs / référencés</option><option value="check">À vérifier / contrôle</option><option value="history">Historique / fermé</option></select></label></div>
          <div class="world-ports-result-head"><span id="worldPortsCount"></span><span>${esc(REG.meta?.version||'')}</span></div>
          <div class="world-ports-grid" id="worldPortsGrid"></div><div class="world-ports-empty" id="worldPortsEmpty" hidden>Aucun port, terminal ou opérateur pour cette recherche.</div>
        </div>
      </section>
    </div>`);
    byId('worldPortsClose')?.addEventListener('click',close);
    byId('worldPortsModal')?.addEventListener('pointerdown',e=>{if(e.target===byId('worldPortsModal'))close();});
    byId('worldPortsSearch')?.addEventListener('input',e=>{query=e.target.value;render();});
    byId('worldPortsCountry')?.addEventListener('change',e=>{country=e.target.value;render();});
    byId('worldPortsStatus')?.addEventListener('change',e=>{status=e.target.value;render();});
    document.querySelectorAll('[data-world-tab]').forEach(btn=>btn.addEventListener('click',()=>setTab(btn.dataset.worldTab)));
    byId('worldPortsGrid')?.addEventListener('click',e=>{
      const showTerms=e.target.closest('[data-world-terminals]');if(showTerms){tab='terminals';query=showTerms.dataset.worldTerminals||'';country='all';status='all';byId('worldPortsSearch').value=query;byId('worldPortsCountry').value='all';byId('worldPortsStatus').value='all';render();return;}
      const showPort=e.target.closest('[data-world-port-parent]');if(showPort){tab='ports';query=showPort.dataset.worldPortParent||'';country='all';status='all';byId('worldPortsSearch').value=query;byId('worldPortsCountry').value='all';byId('worldPortsStatus').value='all';render();return;}
    });
    document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!byId('worldPortsModal')?.hidden)close();});
    byId('worldPortsReferenceBtn')?.addEventListener('click',()=>open());
    render();
  }
  window.C3K_WORLD_PORTS_REFERENCE_UI={open,close,render,setTab};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',build,{once:true});else build();
})();
